  const adj = Array.from({ length: n + 1 }, () => []);
  for (const [u, v] of relations) adj[u].push(v);
  const memo = new Array(n + 1).fill(0);
  const visiting = new Set();
  function dfs(u) {
    if (visiting.has(u)) return -1;
    if (memo[u] > 0) return memo[u];
    visiting.add(u);
    let maxDepth = 0;
    for (const v of adj[u]) {
      const depth = dfs(v);
      if (depth === -1) return -1;
      maxDepth = Math.max(maxDepth, depth);
    }
    visiting.delete(u);
    memo[u] = 1 + maxDepth;
    return memo[u];
  }
  let maxSem = 0;
  for (let i = 1; i <= n; i++) {
    const depth = dfs(i);
    if (depth === -1) return -1;
    maxSem = Math.max(maxSem, depth);
  }
  return maxSem;
}

