  function getHeight(root) {
    const visited = new Set([root]);
    const q = [root];
    let h = 0;
    while (q.length > 0) {
      const sz = q.length;
      for (let i = 0; i < sz; i++) {
        const u = q.shift();
        for (const v of adj[u]) {
          if (!visited.has(v)) { visited.add(v); q.push(v); }
