  const n = graph.length;
  // 0: unvisited, 1: visiting (in stack), 2: safe
  const state = new Array(n).fill(0);
  function dfs(node) {
    if (state[node] !== 0) return state[node] === 2;
    state[node] = 1;
    for (const next of graph[node]) {
