function regionsBySlashes(grid) {
  const n = grid.length;
  // Divide each cell into 4 triangles: 0: top, 1: right, 2: bottom, 3: left
  const total = 4 * n * n;
  const parent = Array.from({ length: total }, (_, i) => i);
  let count = total;
  function find(x) {
    if (parent[x] !== x) parent[x] = find(parent[x]);
    return parent[x];
  }
  function union(x, y) {
    const rx = find(x), ry = find(y);
    if (rx !== ry) {
      parent[rx] = ry;
      count--;
    }
  }
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      const idx = 4 * (r * n + c);
      const char = grid[r][c];
      if (char === '/') {
        union(idx + 0, idx + 3);
        union(idx + 1, idx + 2);
      } else if (char === '\\') {
        union(idx + 0, idx + 1);
        union(idx + 2, idx + 3);
      } else {
        union(idx + 0, idx + 1);
        union(idx + 1, idx + 2);
        union(idx + 2, idx + 3);
      }
      if (r + 1 < n) union(idx + 2, 4 * ((r + 1) * n + c) + 0);
      if (c + 1 < n) union(idx + 1, 4 * (r * n + (c + 1)) + 3);
